<?php
namespace App\Http\Controllers; use App\Enums\UserRole; use App\Models\User; use App\Services\ReferralService; use Illuminate\Http\RedirectResponse; use Illuminate\Http\Request; use Illuminate\Support\Facades\Auth; use Illuminate\Support\Str; use Inertia\Inertia; use Inertia\Response;
class AuthController extends Controller { public function login(): Response { return Inertia::render('Auth/Login'); } public function register(): Response { return Inertia::render('Auth/Register'); } public function authenticate(Request $request): RedirectResponse { $credentials=$request->validate(['email'=>['required','email'],'password'=>['required']]); if (! Auth::attempt($credentials, $request->boolean('remember'))) return back()->with('error','Invalid credentials.'); $request->session()->regenerate(); return redirect()->intended(route('dashboard')); } public function store(Request $request, ReferralService $referrals): RedirectResponse { $data=$request->validate(['name'=>['required','string','max:120'],'email'=>['required','email','unique:users,email'],'phone'=>['nullable','string','max:30'],'password'=>['required','confirmed','min:8'],'ref'=>['nullable','string','exists:users,referral_code']]); $user=User::create(['name'=>$data['name'],'email'=>$data['email'],'phone'=>$data['phone']??null,'password'=>$data['password'],'role'=>UserRole::Customer,'referral_code'=>Str::upper(Str::random(8))]); $user->assignRole(UserRole::Customer->value); if (!empty($data['ref'])) { $referrer=User::where('referral_code',$data['ref'])->first(); if ($referrer && ! $referrer->is($user)) { $user->update(['referred_by'=>$referrer->id]); $referrals->registerReferral($referrer,$user); } } Auth::login($user); return redirect()->route('dashboard'); } public function logout(Request $request): RedirectResponse { Auth::logout(); $request->session()->invalidate(); $request->session()->regenerateToken(); return redirect('/login'); } }
